const busquedas = [
  { query: 'inmobiliaria Chico Bogota', rubro: 'Inmobiliaria' },
  { query: 'firma de abogados Usaquen Bogota', rubro: 'Firma de Abogados' },
  { query: 'agencia de marketing digital Bogota', rubro: 'Agencia Marketing' },
  { query: 'clinica odontologica Cedritos Bogota', rubro: 'Clinica Odontologica' },
  { query: 'firma contable Chapinero Bogota', rubro: 'Firma Contable' },
  { query: 'constructora inmobiliaria proyectos vivienda Bogota', rubro: 'Constructora' },
  { query: 'clinica dermatologica Bogota', rubro: 'Clinica Dermatologica' },
  { query: 'agencia de viajes Bogota', rubro: 'Agencia de Viajes' },
  { query: 'academia de idiomas Bogota', rubro: 'Academia' },
  { query: 'inmobiliaria Santa Barbara Bogota', rubro: 'Inmobiliaria' },
  { query: 'clinica veterinaria Bogota', rubro: 'Clinica Veterinaria' },
  { query: 'empresa de logistica Bogota', rubro: 'Logistica' }
];

const staticData = $getWorkflowStaticData('global');
const idx = ((staticData.ultimoIndice ?? 2) + 1) % busquedas.length;
staticData.ultimoIndice = idx;

return [{ json: busquedas[idx] }];

const places = $input.first().json.places || [];
const rubro = $('Rotador Busqueda Bogota').first().json.rubro;
const existentes = $('Leer Leads Existentes').all().map(i => i.json);

const idsVistos = new Set(existentes.map(r => String(r.Place_ID || '').trim()).filter(Boolean));
const telsVistos = new Set(existentes.map(r => String(r.Telefono_WA || '').trim()).filter(Boolean));
const websVistas = new Set(existentes.map(r => String(r.Web || '').toLowerCase().trim()).filter(w => w && w !== 'sin web'));

const blacklist = [
  'kreston', 'deloitte', 'kpmg', 'pwc', 'ernst', 'bdo', 'mazars',
  'bancolombia', 'davivienda', 'bbva', 'scotiabank', 'occidente', 'bogota s.a',
  'sura', 'sanitas', 'compensar', 'colsanitas', 'famisanar', 'nueva eps',
  'movistar', 'claro', 'tigo', 'wom', 'notaria', 'notaría',
  'gobernacion', 'alcaldia', 'ministerio', 'universidad', 'fundacion', 'fundación',
  'sucursal', 'sede ', 'cajero', 'corresponsal',
  'conjunto residencial', 'conjunto ', 'condominio', 'agrupacion', 'agrupación',
'urbanizacion', 'urbanización', 'edificio', 'propiedad horizontal', 'torres de', 'parque residencial'
];

const escapeHtml = (str) => String(str)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const validos = [];

for (const p of places) {
  if (p.businessStatus !== 'OPERATIONAL') continue;

  const resenas = p.userRatingCount || 0;
  if (resenas < 10 || resenas > 350) continue;

  const nombre = (p.displayName?.text || '').trim();
  if (!nombre) continue;
  const nombreLower = nombre.toLowerCase();
  if (blacklist.some(word => nombreLower.includes(word))) continue;

  const rawTel = (p.nationalPhoneNumber || '').replace(/\D/g, '');
  if (!rawTel.startsWith('3') || rawTel.length !== 10) continue;
  const telefonoWA = '57' + rawTel;

  const placeId = String(p.id || '').trim();
  const webRaw = (p.websiteUri || '').trim();
  const webNorm = webRaw.toLowerCase();

  if (idsVistos.has(placeId) || telsVistos.has(telefonoWA)) continue;
  if (webNorm && websVistas.has(webNorm)) continue;

  idsVistos.add(placeId);
  telsVistos.add(telefonoWA);
  if (webNorm) websVistas.add(webNorm);

  const esSoloRed = /instagram\.com|facebook\.com|linktr\.ee|wa\.me|api\.whatsapp\.com|tiktok\.com/.test(webNorm);
  const sinWeb = !webRaw || esSoloRed;
  const web = webRaw || 'Sin web';

  let angulo = 'Automatizacion IA / WA';
  let mensaje = '';

  if (rubro === 'Agencia Marketing') {
    angulo = 'Alianza Tecnica IA / n8n';
    mensaje = `Hola ${nombre}, ¿cómo están? Vi su agencia en Google Maps. \n\nSoy Nicolás Valenzuela, ingeniero de software e IA; apoyo a agencias como aliado técnico implementando agentes de WhatsApp con IA y automatizaciones a medida para sus clientes. \n\n¿Con quién podría compartirles un par de demos rápidas?`;
  } else if (sinWeb) {
    angulo = 'Web de Captacion';
    mensaje = `Hola ${nombre}, ¿cómo están? Vi su perfil en Google Maps y noté que aún no tienen un sitio web propio enfocado en captar clientes. \n\nSoy Nicolás Valenzuela, ingeniero de software e IA; ayudo a negocios de ${rubro.toLowerCase()} a lanzar páginas web rápidas de conversión y agendamiento. \n\n¿Podría compartirles una muestra rápida?`;
  } else {
    mensaje = `Hola ${nombre}, ¿cómo están? Vi su perfil y sitio web en Google Maps. \n\nSoy Nicolás Valenzuela, ingeniero de software e IA; ayudo a negocios de ${rubro.toLowerCase()} a automatizar la atención por WhatsApp y la calificación de consultas con IA para no perder clientes. \n\n¿Podría compartirles una muestra rápida?`;
  }

  const linkWA = `https://wa.me/${telefonoWA}?text=${encodeURIComponent(mensaje)}`;

  validos.push({
    json: {
      Fecha: hoy,
      Place_ID: placeId,
      Negocio: nombre,
      Negocio_HTML: escapeHtml(nombre),
      Rubro: rubro,
      Telefono_WA: telefonoWA,
      Web: web,
      Web_HTML: escapeHtml(web),
      Resenas: resenas,
      Rating: p.rating || 0,
      Angulo: angulo,
      Mensaje: mensaje,
      Mensaje_HTML: escapeHtml(mensaje),
      Estado: 'Pendiente',
      Link_WA: linkWA
    }
  });
}

return validos.slice(0, 8);

